// The .NET base class library as its reference assemblies and XML docs
// describe it, generated by tools/csharp_vocab into csharp_lsp_bcl.cpp.
// Plain data for mep's own C# language server: completion, hover,
// signature help and base-type walks, without needing .NET at build or run
// time.
#pragma once

#include <cstddef>
#include <cstdint>

struct CsBclType {
    const char *name;        // full name with type parameters: "System.Collections.Generic.List<T>"
    const char *kind;        // class, static class, struct, record, record struct, interface, enum, delegate
    const char *base;        // full name of the base type ("System.Object"), an enum's underlying type, or ""
    const char *interfaces;  // every interface it implements, full names, ';'-separated
    const char *signature;   // the declaration as C# prints it ("class List<T>", "delegate void Action<in T>(T obj)")
    const char *doc;         // the <summary>, plain text with `code` spans
};

enum CsBclMemberKind : uint8_t {
    kCsBclMethod = 0,
    kCsBclConstructor = 1,
    kCsBclProperty = 2,
    kCsBclField = 3,
    kCsBclEvent = 4,
    kCsBclEnumMember = 5,
    kCsBclIndexer = 6,
};

enum CsBclMemberFlags : uint8_t { kCsBclStatic = 1, kCsBclExtension = 2, kCsBclConst = 4, kCsBclProtected = 8 };

struct CsBclMember {
    const char *owner;      // the type's CsBclType::name
    const char *name;       // a constructor's is its type's simple name
    uint8_t kind;           // CsBclMemberKind
    uint8_t flags;          // CsBclMemberFlags
    const char *signature;  // as C# prints it: "public string Substring(int startIndex, int length)"
    const char *params;     // "(int startIndex, int length)" for methods/constructors, "[int index]" for indexers
    const char *type;       // return / property / field type, full name ("string", "System.Collections.Generic.List<T>")
    const char *doc;        // the <summary>, plain text
};

const char *CsBclVersion();  // the reference pack version the table was generated from
// Sorted by name (ordinal).
const CsBclType *CsBclTypes(size_t *count);
// Grouped by owner in CsBclTypes' order; declaration order within a type, overloads adjacent.
const CsBclMember *CsBclMembers(size_t *count);
